void mainImage(out vec4 fragColor, in vec2 fragCoord) {
 vec2 uv = fragCoord / iResolution.xy;
 vec3 src = texture(iChannel0, uv).rgb;
 float l = clamp(dot(src, vec3(0.2126,0.7152,0.0722)) * U.p0.x, 0.0, 1.0);
 vec3 cold = vec3(0.015,0.01,0.09);
 vec3 blue = vec3(0.1,0.05,0.8);
 vec3 pink = vec3(0.95,0.02,0.35);
 vec3 hot = vec3(1.0,0.9,0.12);
 vec3 c = mix(cold,blue,smoothstep(0.0,0.3,l));
 c = mix(c,pink,smoothstep(0.25,0.65,l));
 c = mix(c,hot,smoothstep(0.6,1.0,l));
 fragColor = vec4(mix(src,c,clamp(U.p0.y,0.0,1.0)),1.0);
}
